import sys
from collections import defaultdict

def find_index_to_remove(n, b):
    if n == 2:
        return 1

    freq = defaultdict(int)
    min_val = min(b)
    max_val = max(b)

    for num in b:
        freq[num] += 1

    if max_val == min_val:
        return 1

    for d in range(1, (max_val - min_val) // (n - 1) + 1):
        valid = True
        count = 0
        current = min_val

        while current <= max_val:
            if current not in freq:
                valid = False
                break
            count += freq[current]
            if count > 1 and freq[current] != 1:
                valid = False
                break
            current += d

        if valid and count == n - 1:
            for i in range(n):
                if b[i] == current - d:
                    return i + 1

    return -1

